function validate([hours]) {
  if (!Array.isArray(hours) || hours.length < 1 || hours.length > 500000) return 'hours needs 1 to 500000 values.';
  if (hours.some(h => !Number.isInteger(h) || h < 1 || h > 1000000000)) return 'Each hour count is an integer from 1 to 10^9.';
  return null;
}

