function countCompleteDayPairs(hours) {
  const seen = new Map();
  let pairs = 0;

  for (const hour of hours) {
    const remainder = hour % 24;
    const needed = (24 - remainder) % 24;
    pairs += seen.get(needed) ?? 0;
    seen.set(remainder, (seen.get(remainder) ?? 0) + 1);
  }
  return pairs;
}

