function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Hours built from a few remainders that complete each other, so pairs are common.
  const fromRemainders = (remainders, top) => {
    const remainder = remainders[pick(0, remainders.length - 1)];
    return remainder + 24 * pick(remainder === 0 ? 1 : 0, top);
  };
  if (size === 'large') {
    const style = pick(0, 2);
    return [Array.from({ length: 2000 }, () => {
      if (style === 0) return pick(1, 1000000000);
      if (style === 1) return 24 * pick(1, 41666666);
      return fromRemainders([0, 12, 5, 19, 6, 18, 23], 41666665);
    })];
  }
  const n = pick(1, 10);
  const remainders = [[0, 12], [1, 23, 2, 22], [0, 6, 12, 18, 7, 17]][pick(0, 2)];
  return [Array.from({ length: n }, () => rand() < 0.2 ? pick(1, 1000000000) : fromRemainders(remainders, 5))];
}
